function [r] = orem(x, y)
%OREM  Octave's rem(x, y) as finddays takes it: x - fix(x/y) y, 0 when x/y is whole, with the sign of x.
%   x: real[1] (passed a plain number)
%   y: real[1] (passed a plain number)
%   returns r: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = 0;
    if (y == 0)
        r = NaN;
    else
        q = (x / y);
        nq = q;
        if isfinite(q)
            nq = floor((q + 0.5));
        end
        if (nq == q)
            r = 0;
        else
            r = (x - (y * fix(q)));
